    },
    {
      "section": "7.6",
      "label": "(2)",
      "text": "The PCA pump shall be cleaned and disinfected 154 after use.",
      "id": null
    },
    {
      "section": "7.7",
      "label": "(1)",
      "text": "The PCA pump shall minimize drug leakage 155.",
      "id": null
    },
    {
      "section": "8.1",
      "label": "(1)",
      "text": "Clinicians authorization to operate the PCA pump must be authenticated.156 (UC1.4 §4.1.1)",
      "id": null
    },
    {
      "section": "8.1",
      "label": "(2)",
      "text": "Patient’s identity and admittance to the hospital must be authenticated. 157 (UC1.6 §4.1.1)",
      "id": null
    },
    {
      "section": "8.1",
      "label": "(3)",
      "text": "Drug container must have a valid prescription for the particular patient to be infused by the PCA pump.158 (UC1.8 §4.1.1)",
      "id": null
    },
    {
      "section": "8.1",
      "label": "(4)",
      "text": "Drug library information shall be authenticated before it is accepted. 159",
